10	/**
11	 * Replays the owner an {@code Idempotency-Key} first created: loads it by the id
12	 * {@link CheckIdempotency} resolved from the key and responds 200, as opposed to
13	 * {@link RespondWithOwnerCreated}'s 201 for a fresh create.
14	 */
15	public class RespondWithExistingOwner {
16	
17	    public void service(@Parameter Integer ownerId, OwnerRepository ownerRepository,
18	            OwnerMapper ownerMapper, ObjectResponse<OwnerDto> response) {
19	        Owner owner = ownerRepository.findById(ownerId);
20	        response.send(ownerMapper.toOwnerDto(owner));
21	    }
22	}
