1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.web.bind.annotation.RequestBody;
6	
7	/**
8	 * Resolves the address of a create request to its canonical form (see
9	 * {@link AddressNormalizer#resolve(String, String, String)}) before any other rule runs. The
10	 * structured form ({@code addressLine1}/{@code addressLine2}) is preferred when supplied, otherwise
11	 * the flat {@code address} is used; either way the lines and the composed flat address are
12	 * normalized. Running first means the required-field check ({@link ValidateOwnerFields}) rejects an
13	 * address that is blank after normalization and {@link BuildOwner} stores — and later responses
14	 * return — the normalized form. Binds the request body once and republishes it for the rest of the
15	 * pipeline.
16	 */
17	public class NormalizeAddress {
18	
19	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> normalized) {
20	        AddressNormalizer.Normalized address = AddressNormalizer.resolve(
21	                request.getAddressLine1(), request.getAddressLine2(), request.getAddress());
22	        request.setAddressLine1(address.addressLine1());
23	        request.setAddressLine2(address.addressLine2());
24	        request.setAddress(address.address());
25	        normalized.set(request);
26	    }
27	}
