1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.Optional;
5	import java.util.concurrent.ConcurrentHashMap;
6	
7	import org.springframework.stereotype.Component;
8	
9	/**
10	 * Remembers which owner an {@code Idempotency-Key} first created, so a repeated create carrying an
11	 * already-seen key replays the original owner instead of inserting a duplicate. Keyed on the raw
12	 * header value; the stored value is the generated owner id. {@link #record} keeps the first winner,
13	 * so concurrent retries all resolve to the same owner. Application-scoped and in-memory: the mapping
14	 * outlives a single request but is not itself persisted.
15	 */
16	@Component
17	public class IdempotencyStore {
18	
19	    private final Map<String, Integer> ownerIdByKey = new ConcurrentHashMap<>();
20	
21	    /** The id of the owner first created under {@code key}, or empty when the key is new. */
22	    public Optional<Integer> lookup(String key) {
23	        return Optional.ofNullable(ownerIdByKey.get(key));
24	    }
25	
26	    /** Records the owner created under {@code key}, keeping the first winner for repeated keys. */
27	    public void record(String key, int ownerId) {
28	        ownerIdByKey.putIfAbsent(key, ownerId);
29	    }
30	}
