1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Canonical address normalization shared by the create pipeline: {@link NormalizeAddress} stores and
7	 * returns the normalized form and {@link HouseholdNormalizer} compares addresses by it. Not a pipeline
8	 * step, so it is free to expose plain helpers.
9	 */
10	public final class AddressNormalizer {
11	
12	    /** Common street-type abbreviations expanded to their full word (keys are already upper-cased). */
13	    private static final Map<String, String> ABBREVIATIONS = Map.of(
14	            "ST", "STREET",
15	            "RD", "ROAD",
16	            "AVE", "AVENUE");
17	
18	    private AddressNormalizer() {
19	    }
20	
21	    /**
22	     * Normalizes an address to its canonical stored/compared form: outer whitespace trimmed, internal
23	     * runs of whitespace collapsed to a single space, upper-cased, and common street-type
24	     * abbreviations expanded as whole words ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code
25	     * ROAD}, {@code AVE}&rarr;{@code AVENUE}). A {@code null} or blank address normalizes to an empty
26	     * string. Idempotent: normalizing an already-normalized address returns it unchanged.
27	     */
28	    public static String normalize(String address) {
29	        if (address == null) {
30	            return "";
31	        }
32	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
33	        if (collapsed.isEmpty()) {
34	            return "";
35	        }
36	        String[] tokens = collapsed.split(" ");
37	        StringBuilder result = new StringBuilder(collapsed.length());
38	        for (int i = 0; i < tokens.length; i++) {
39	            if (i > 0) {
40	                result.append(' ');
41	            }
42	            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
43	        }
44	        return result.toString();
45	    }
46	
47	    /**
48	     * Composes the flat address from a structured address: the {@link #normalize(String) normalized}
49	     * first line, with a single space and the normalized second line appended when a second line is
50	     * present. A blank second line yields just the first line.
51	     */
52	    public static String compose(String addressLine1, String addressLine2) {
53	        String line1 = normalize(addressLine1);
54	        String line2 = normalize(addressLine2);
55	        if (line2.isEmpty()) {
56	            return line1;
57	        }
58	        return line1.isEmpty() ? line2 : line1 + " " + line2;
59	    }
60	
61	    /**
62	     * Resolves an owner's canonical address from a request that may use the structured form
63	     * ({@code addressLine1}/{@code addressLine2}) or the flat {@code address}. The structured form is
64	     * preferred whenever {@code addressLine1} is non-blank: each line is normalized and the flat
65	     * address is their {@link #compose(String, String) composition}. Otherwise only the flat address
66	     * is normalized and no structured lines are kept, keeping the contract backward-compatible.
67	     */
68	    public static Normalized resolve(String addressLine1, String addressLine2, String flatAddress) {
69	        String line1 = normalize(addressLine1);
70	        if (line1.isEmpty()) {
71	            return new Normalized(null, null, normalize(flatAddress));
72	        }
73	        String line2 = normalize(addressLine2);
74	        return new Normalized(line1, line2.isEmpty() ? null : line2, compose(addressLine1, addressLine2));
75	    }
76	
77	    /**
78	     * A resolved address: the normalized structured lines ({@code null} when the flat form was used
79	     * or a line was absent) and the flat {@code address} to store and return.
80	     */
81	    public record Normalized(String addressLine1, String addressLine2, String address) {
82	    }
83	}
