1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Canonical telephone normalization shared by the create pipeline: {@link NormalizeTelephone} stores
8	 * the E.164 form, {@link IdentityKey} uses it for the telephone part of the duplicate key and
9	 * {@link ValidateTelephoneLength} checks its national-number length. Not a pipeline step, so it is
10	 * free to expose plain helpers.
11	 */
12	public final class TelephoneNormalizer {
13	
14	    /** Minimum digits after the '+' for a valid E.164 number. */
15	    private static final int MIN_E164_DIGITS = 8;
16	
17	    /** Maximum digits after the '+' for a valid E.164 number. */
18	    private static final int MAX_E164_DIGITS = 15;
19	
20	    /** Default country code assumed when no leading '+' is present. */
21	    private static final String DEFAULT_COUNTRY_CODE = "61";
22	
23	    /**
24	     * Required national-number digit count per E.164 country code. Ordered longest code first so
25	     * {@link #hasValidNationalLength(String)} matches the most specific prefix (e.g. '61' before '1').
26	     */
27	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY = new LinkedHashMap<>();
28	
29	    static {
30	        NATIONAL_LENGTH_BY_COUNTRY.put("61", 9); // Australia
31	        NATIONAL_LENGTH_BY_COUNTRY.put("1", 10); // NANP (e.g. US)
32	    }
33	
34	    private TelephoneNormalizer() {
35	    }
36	
37	    /**
38	     * Converts a raw telephone to canonical E.164 form, or returns {@code null} when it cannot form a
39	     * valid E.164 number. A leading '+' and country code are kept when present; otherwise the default
40	     * country code '+61' is assumed and a single leading '0' is dropped from the national digits.
41	     * Spaces, dashes and brackets (any non-digit) are stripped. The result must have 8 to 15 digits
42	     * after the '+'.
43	     */
44	    public static String toE164(String telephone) {
45	        if (telephone == null) {
46	            return null;
47	        }
48	        boolean hasCountryCode = telephone.trim().startsWith("+");
49	        String digits = telephone.replaceAll("\\D", "");
50	        if (!hasCountryCode) {
51	            if (digits.startsWith("0")) {
52	                digits = digits.substring(1);
53	            }
54	            digits = DEFAULT_COUNTRY_CODE + digits;
55	        }
56	        if (digits.length() < MIN_E164_DIGITS || digits.length() > MAX_E164_DIGITS) {
57	            return null;
58	        }
59	        return "+" + digits;
60	    }
61	
62	    /** Size of each national-digit group in the human-readable display form. */
63	    private static final int DISPLAY_GROUP_SIZE = 3;
64	
65	    /**
66	     * Formats a canonical E.164 number for humans as its country code, a space, then the national
67	     * digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The country code is
68	     * identified from {@link #NATIONAL_LENGTH_BY_COUNTRY} (longest match first); a number whose
69	     * country code has no configured rule simply has all its digits grouped after the '+'. Expects
70	     * the canonical form produced by {@link #toE164(String)}; a value not in that form is returned
71	     * unchanged.
72	     */
73	    public static String toDisplay(String e164) {
74	        if (e164 == null || !e164.startsWith("+")) {
75	            return e164;
76	        }
77	        String digits = e164.substring(1);
78	        for (String countryCode : NATIONAL_LENGTH_BY_COUNTRY.keySet()) {
79	            if (digits.startsWith(countryCode)) {
80	                return "+" + countryCode + " " + groupInThrees(digits.substring(countryCode.length()));
81	            }
82	        }
83	        return "+" + groupInThrees(digits);
84	    }
85	
86	    /** Splits a run of digits into space-separated groups of {@link #DISPLAY_GROUP_SIZE}. */
87	    private static String groupInThrees(String digits) {
88	        StringBuilder grouped = new StringBuilder();
89	        for (int i = 0; i < digits.length(); i++) {
90	            if (i > 0 && i % DISPLAY_GROUP_SIZE == 0) {
91	                grouped.append(' ');
92	            }
93	            grouped.append(digits.charAt(i));
94	        }
95	        return grouped.toString();
96	    }
97	
98	    /**
99	     * Whether an E.164 number's national-number length matches what its country code requires (e.g.
100	     * '+61' expects 9 national digits, '+1' expects 10). Numbers whose country code has no configured
101	     * rule are accepted, so this only rejects a wrong length for a known country. Expects the canonical
102	     * form produced by {@link #toE164(String)}.
103	     */
104	    public static boolean hasValidNationalLength(String e164) {
105	        if (e164 == null || !e164.startsWith("+")) {
106	            return false;
107	        }
108	        String digits = e164.substring(1);
109	        for (Map.Entry<String, Integer> rule : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
110	            String countryCode = rule.getKey();
111	            if (digits.startsWith(countryCode)) {
112	                return digits.length() - countryCode.length() == rule.getValue();
113	            }
114	        }
115	        return true;
116	    }
117	}
