2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.util.Sha256;
5	
6	/**
7	 * Canonical household identity shared by the create pipeline. A household is keyed on
8	 * <em>last name plus postcode</em>: the last name is compared case-insensitively with runs of
9	 * whitespace collapsed to a single space and outer whitespace trimmed, and the postcode is compared
10	 * verbatim. Owners with equal keys are the same household and therefore share the same
11	 * {@link #id(String, String) household id}, which is a pure, stable function of those two fields — so
12	 * it is stamped on every owner at creation ({@link AssignHousehold}) rather than looked up.
13	 *
14	 * <p>The id feeds every rule that keys off the household: the duplicate block
15	 * ({@link EnsureUniqueIdentity}), the household-size count ({@link CountHousehold}) and the
16	 * possible-duplicate flag ({@link FlagPossibleDuplicate}) all decide membership with
17	 * {@link #belongsTo(Owner, String)}. Not a pipeline step, so it is free to expose plain helpers.
18	 */
19	public final class HouseholdNormalizer {
20	
21	    private HouseholdNormalizer() {
22	    }
23	
24	    /**
25	     * The stable household identifier for an owner: the first 12 hex characters of the SHA-256 of the
26	     * household {@link #key(String, String) key}. Owners with equal keys share the same id, and the id
27	     * never changes for a given (last name, postcode), so it can be recomputed rather than stored.
28	     */
29	    public static String id(String lastName, String postcode) {
30	        return Sha256.prefix(key(lastName, postcode), 12);
31	    }
32	
33	    /**
34	     * Builds the canonical household key: the normalized last name and the postcode joined by '|'.
35	     * Two owners belong to the same household when their keys are equal. Either field may be
36	     * {@code null}, which normalizes to an empty token.
37	     */
38	    public static String key(String lastName, String postcode) {
39	        return normalizeName(lastName) + "|" + orEmpty(postcode);
40	    }
41	
42	    /**
43	     * Whether {@code owner} belongs to the household identified by {@code householdId}, i.e. its own
44	     * (last name, postcode) hashes to that id. {@code false} when {@code householdId} is {@code null}.
45	     */
46	    public static boolean belongsTo(Owner owner, String householdId) {
47	        return householdId != null && householdId.equals(id(owner.getLastName(), owner.getPostcode()));
48	    }
49	
50	    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
51	    private static String normalizeName(String value) {
52	        if (value == null) {
53	            return "";
54	        }
55	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
56	    }
57	
58	    private static String orEmpty(String value) {
59	        return value == null ? "" : value;
60	    }
61	}
